        tagOnPause: mapValueOfType<bool>(json, r'tagOnPause'),
        task1: mapValueOfType<String>(json, r'task1'),
        task2: mapValueOfType<String>(json, r'task2'),
        task3: mapValueOfType<String>(json, r'task3'),
        template: mapValueOfType<String>(json, r'template'),
        topic: mapValueOfType<String>(json, r'topic'),
        type: mapValueOfType<String>(json, r'type'),
        unit: mapValueOfType<String>(json, r'unit'),
        videoId: mapValueOfType<String>(json, r'videoId'),
        videoLength: mapValueOfType<String>(json, r'videoLength'),
        wordCountMap: mapCastOfType<String, int>(json, r'wordCountMap') ?? const {},
      );
    }
    return null;
  }

  static List<Video> listFromJson(dynamic json, {bool growable = false,}) {
    final result = <Video>[];
    if (json is List && json.isNotEmpty) {
      for (final row in json) {
        final value = Video.fromJson(row);
        if (value != null) {
          result.add(value);
        }
      }
    }
    return result.toList(growable: growable);
  }

  static Map<String, Video> mapFromJson(dynamic json) {
    final map = <String, Video>{};
    if (json is Map && json.isNotEmpty) {
      json = json.cast<String, dynamic>(); // ignore: parameter_assignments
      for (final entry in json.entries) {
        final value = Video.fromJson(entry.value);
        if (value != null) {
          map[entry.key] = value;
        }
      }
    }
    return map;
  }

  // maps a json object with a list of Video-objects as value to a dart map
  static Map<String, List<Video>> mapListFromJson(dynamic json, {bool growable = false,}) {
    final map = <String, List<Video>>{};
    if (json is Map && json.isNotEmpty) {
      // ignore: parameter_assignments
      json = json.cast<String, dynamic>();
      for (final entry in json.entries) {
        map[entry.key] = Video.listFromJson(entry.value, growable: growable,);
      }
    }
    return map;
  }

  /// The list of required keys that must be present in a JSON.
  static const requiredKeys = <String>{
  };
